export const byId = <T extends { id: string }>(list: T[], id: string) => list.find((x) => x.id === id);
export const initials = (name: string) => name.split(" ").map((p) => p[0]).slice(0, 2).join("");

/** Progress and points for one learner on one piece of content, kept consistent with their status. */
export function progressFor(l: Learner, contentId: string): { progress: number; points: number } {
  const st = l.status[contentId];
  const seed = (l.name.length * 7 + contentId.length * 13) % 5;
  const progress = st === "completed" || st === "failed" ? 100 : st === "in-progress" ? 25 + seed * 14 : st === "overdue" ? 10 + seed * 8 : 0;
  const points = st === "completed" ? 100 - seed * 5 : st === "failed" ? 30 + seed * 5 : Math.round(progress * 0.8);
  return { progress, points };
}

"use client";

import { createContext, useCallback, useContext, useMemo, useRef, useState, type ReactNode } from "react";
import { usePathname } from "next/navigation";
import { COMMENTS, CONTENT, LEARNERS, PEOPLE, TODOS, TRAINER_POOL, type Comment, type Content, type Kind, type Todo } from "./data";

type Store = {
  content: Content[];
  todos: Todo[];
  comments: Record<string, Comment[]>;
  toast: string;
  say: (t: string) => void;
  addContent: (title: string, kind: Kind) => string;
  patch: (id: string, p: Partial<Content>) => void;
  remove: (id: string) => void;
  toggleFavorite: (id: string) => void;
  assign: (id: string, people: string[]) => void;
  addSection: (id: string) => void;
  addChapter: (id: string, sectionId: string) => void;
  addTrainer: (id: string) => void;
  addTodo: (title: string) => void;
  toggleTodo: (id: string) => void;
  addComment: (id: string, text: string) => void;
  graded: string[];
  grade: (quizId: string) => void;
};

const Ctx = createContext<Store | null>(null);
let n = 1;
const uid = () => `x${Date.now().toString(36)}${n++}`;

export function useLms() {
  const c = useContext(Ctx);
  if (!c) throw new Error("useLms must be used inside LmsProvider");
  return c;
}

/** The URL prefix the template is mounted at, so links work at /lms, /preview/lms or anywhere else. */
export function useBase() {
  const path = usePathname();
  const i = path.indexOf("/lms");
  return i === -1 ? "" : path.slice(0, i + "/lms".length);
}

/** Keeps everything in memory. Replace these actions with calls to your own API. */
export function LmsProvider({ children }: { children: ReactNode }) {
  const [content, setContent] = useState<Content[]>(CONTENT);
  const [todos, setTodos] = useState<Todo[]>(TODOS);
  const [comments, setComments] = useState<Record<string, Comment[]>>({ "interface-foundations": COMMENTS });
  const [graded, setGraded] = useState<string[]>([]);
  const [toast, setToast] = useState("");
  const timer = useRef<ReturnType<typeof setTimeout> | undefined>(undefined);

  const say = useCallback((t: string) => {
    setToast(t);
    clearTimeout(timer.current);
    timer.current = setTimeout(() => setToast(""), 2200);
  }, []);

  const patch = useCallback((id: string, p: Partial<Content>) => setContent((l) => l.map((c) => (c.id === id ? { ...c, ...p } : c))), []);

  const value = useMemo<Store>(
    () => ({
      content,
      todos,
      comments,
      toast,
      say,
      graded,
      patch,
      addContent: (title, kind) => {
        const id = `${title.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "") || "untitled"}-${uid().slice(-3)}`;
        setContent((l) => [
          {
            id,
            title,
            kind,
            published: false,
            tags: ["Not Urgent"],
            language: "English",
            author: PEOPLE[0].name,
            created: "Today",
            edited: "Just now",
            description: "Add a short description so learners know what to expect.",
            points: 50,
            hours: 1,
            sections: [{ id: "s1", title: "Section one", chapters: [{ id: "s1-0", title: "Chapter one" }] }],
            art: l.length % 4,
            assigned: [],
            completed: 0,
            favorite: false,
            archived: false,
            project: "Northwind Studio",
            trainers: [PEOPLE[0].id],
          },
          ...l,
        ]);
        say("Content created");
        return id;
      },
      remove: (id) => {
        setContent((l) => l.filter((c) => c.id !== id));
        say("Content deleted");
      },
      toggleFavorite: (id) => setContent((l) => l.map((c) => (c.id === id ? { ...c, favorite: !c.favorite } : c))),
      assign: (id, people) => {
        setContent((l) => l.map((c) => (c.id === id ? { ...c, assigned: Array.from(new Set([...c.assigned, ...people])) } : c)));
        say(people.length ? `Assigned to ${people.length} ${people.length === 1 ? "person" : "people"}` : "Nobody selected");
      },
      addSection: (id) =>
        setContent((l) =>
          l.map((c) => (c.id === id ? { ...c, edited: "Just now", sections: [...c.sections, { id: uid(), title: `New section ${c.sections.length + 1}`, chapters: [] }] } : c))
        ),
      addChapter: (id, sectionId) =>
        setContent((l) =>
          l.map((c) =>
            c.id === id
              ? { ...c, edited: "Just now", sections: c.sections.map((s) => (s.id === sectionId ? { ...s, chapters: [...s.chapters, { id: uid(), title: `New chapter ${s.chapters.length + 1}` }] } : s)) }
              : c
          )
        ),
      addTrainer: (id) =>
        setContent((l) =>
          l.map((c) => {
            if (c.id !== id) return c;
            const next = TRAINER_POOL.find((p) => !c.trainers.includes(p.id)) ?? LEARNERS.find((p) => !c.trainers.includes(p.id));
            return next ? { ...c, trainers: [...c.trainers, next.id] } : c;
          })
        ),
      addTodo: (title) => setTodos((l) => [{ id: uid(), title, done: false }, ...l]),
      toggleTodo: (id) => setTodos((l) => l.map((t) => (t.id === id ? { ...t, done: !t.done } : t))),
      addComment: (id, text) => setComments((m) => ({ ...m, [id]: [...(m[id] ?? []), { id: uid(), author: PEOPLE[0].name, text, at: "Just now" }] })),
      grade: (quizId) => {
        setGraded((g) => [...g, quizId]);
        say("Graded");
      },
    }),
    [content, todos, comments, toast, say, graded, patch]
  );

  return <Ctx.Provider value={value}>{children}</Ctx.Provider>;
}

"use client";

import { useEffect, type ReactNode } from "react";
import { AnimatePresence, motion } from "framer-motion";
import { BookOpen, ClipboardCheck, FileText, GraduationCap, HelpCircle, Route, X } from "lucide-react";
import { initials, type Kind, type Status } from "@/lib/lms/data";
import { cn } from "@/lib/utils";

export const KIND_META: Record<Kind, { label: string; icon: typeof FileText; bg: string }> = {
  course: { label: "Course", icon: GraduationCap, bg: "bg-chart-5" },
  page: { label: "Page", icon: FileText, bg: "bg-primary" },
  assignment: { label: "Assignment", icon: ClipboardCheck, bg: "bg-chart-2" },
  quiz: { label: "Quiz", icon: HelpCircle, bg: "bg-chart-4" },
  path: { label: "Learning Path", icon: Route, bg: "bg-chart-3" },
};

export function KindIcon({ kind, className }: { kind: Kind; className?: string }) {
  const m = KIND_META[kind] ?? { icon: BookOpen, bg: "bg-muted" };
  const Icon = m.icon;
  return (
    <span className={cn("grid size-7 shrink-0 place-items-center rounded-lg text-white", m.bg, className)}>
      <Icon className="size-3.5" />
    </span>
  );
}

const TONES = ["bg-chart-1/15 text-chart-1", "bg-chart-5/20 text-chart-5", "bg-chart-2/20 text-chart-2", "bg-chart-3/15 text-chart-3", "bg-chart-4/20 text-chart-4"];

export function Avatar({ name, size = 36, className }: { name: string; size?: number; className?: string }) {
  const tone = TONES[(name.charCodeAt(0) + name.length) % TONES.length];
  return (
    <span aria-hidden style={{ width: size, height: size, fontSize: size * 0.36 }} className={cn("grid shrink-0 place-items-center rounded-full font-semibold", tone, className)}>
      {initials(name)}
    </span>
  );
}

export const STATUS_DOT: Record<Status, string> = {
  "not-started": "bg-muted-foreground/50",
  "in-progress": "bg-chart-5",
  completed: "bg-chart-1",
  overdue: "bg-destructive",
  failed: "bg-chart-2",
};

/** A small circular progress ring. */
export function Ring({ value, size = 22, stroke = 3, className }: { value: number; size?: number; stroke?: number; className?: string }) {
  const r = (size - stroke) / 2;
  const c = 2 * Math.PI * r;
  return (
    <svg width={size} height={size} viewBox={`0 0 ${size} ${size}`} className={cn("-rotate-90", className)} aria-hidden>
      <circle cx={size / 2} cy={size / 2} r={r} fill="none" strokeWidth={stroke} className="stroke-muted" />
      <motion.circle
        cx={size / 2}
        cy={size / 2}
        r={r}
        fill="none"
        strokeWidth={stroke}
        strokeLinecap="round"
        className="stroke-chart-4"
        strokeDasharray={c}
        initial={{ strokeDashoffset: c }}
        animate={{ strokeDashoffset: c * (1 - value / 100) }}
        transition={{ duration: 0.8, ease: [0.22, 1, 0.36, 1] }}
      />
    </svg>
  );
}

/** Flat generated artwork for content covers. Colours come from the theme, so it never needs image files. */
export function Art({ variant, className }: { variant: number; className?: string }) {
  const v = variant % 4;
  const palettes = [
    ["fill-chart-1", "fill-chart-2", "fill-card"],
    ["fill-chart-2", "fill-chart-1", "fill-card"],
    ["fill-chart-5", "fill-chart-2", "fill-card"],
    ["fill-chart-2", "fill-chart-5", "fill-card"],
  ][v];
  const bg = ["bg-chart-1/25", "bg-chart-2/25", "bg-chart-5/25", "bg-chart-3/20"][v];
  return (
    <div className={cn("relative overflow-hidden", bg, className)}>
      <svg viewBox="0 0 320 120" preserveAspectRatio="xMidYMid slice" className="absolute inset-0 size-full" aria-hidden>
        {v === 0 && (
          <>
            <rect x="60" y="22" width="200" height="86" rx="10" className={palettes[2]} />
            <rect x="74" y="36" width="90" height="10" rx="5" className={palettes[0]} />
            <rect x="74" y="56" width="140" height="8" rx="4" className="fill-muted" />
            <rect x="74" y="72" width="110" height="8" rx="4" className="fill-muted" />
            <circle cx="236" cy="44" r="18" className={palettes[1]} />
          </>
        )}
        {v === 1 && (
          <>
            <path d="M40 100 L110 70 L160 82 L230 36 L276 24" strokeWidth="8" strokeLinecap="round" strokeLinejoin="round" fill="none" className="stroke-foreground/80" />
            <circle cx="110" cy="70" r="9" className={palettes[1]} />
            <circle cx="230" cy="36" r="11" className={palettes[0]} />
            <rect x="40" y="104" width="240" height="6" rx="3" className="fill-foreground/10" />
          </>
        )}
        {v === 2 && (
          <>
            {[0, 1, 2, 3].map((i) => (
              <rect key={i} x={50 + i * 60} y={24 + (i % 2) * 24} width="48" height="44" rx="8" className={i % 2 ? palettes[1] : palettes[0]} />
            ))}
            <circle cx="160" cy="92" r="16" className={palettes[2]} />
          </>
        )}
        {v === 3 && (
          <>
            <circle cx="90" cy="60" r="34" className={palettes[0]} />
            <rect x="140" y="30" width="130" height="14" rx="7" className={palettes[2]} />
            <rect x="140" y="54" width="100" height="14" rx="7" className={palettes[2]} />
            <rect x="140" y="78" width="120" height="14" rx="7" className={palettes[1]} />
          </>
        )}
      </svg>
    </div>
  );
}

export function Modal({ open, onClose, title, children, width = "max-w-md" }: { open: boolean; onClose: () => void; title: string; children: ReactNode; width?: string }) {
  useEffect(() => {
    if (!open) return;
    const k = (e: KeyboardEvent) => e.key === "Escape" && onClose();
    window.addEventListener("keydown", k);
    return () => window.removeEventListener("keydown", k);
  }, [open, onClose]);
  return (
    <AnimatePresence>
      {open && (
        <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="fixed inset-0 z-50 grid place-items-center bg-black/40 p-4 backdrop-blur-[2px]" onClick={onClose}>
          <motion.div
            role="dialog"
            aria-modal="true"
            aria-label={title}
            initial={{ opacity: 0, y: 12, scale: 0.98 }}
            animate={{ opacity: 1, y: 0, scale: 1 }}
            exit={{ opacity: 0, y: 8, scale: 0.98 }}
            transition={{ duration: 0.2 }}
            onClick={(e) => e.stopPropagation()}
            className={cn("w-full rounded-2xl border bg-card p-6 shadow-2xl", width)}
          >
            <div className="mb-4 flex items-center justify-between">
              <h2 className="text-lg font-semibold tracking-tight">{title}</h2>
              <button type="button" onClick={onClose} aria-label="Close" className="grid size-8 place-items-center rounded-lg text-muted-foreground hover:bg-muted hover:text-foreground">
                <X className="size-4" />
              </button>
            </div>
            {children}
          </motion.div>
        </motion.div>
      )}
    </AnimatePresence>
  );
}

